import {jest} from '@jest/globals';
import type {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {MessageChunk} from '../../types/ai.js';
import {deferred} from '../wsTestSupport.js';

describe('conversation list acceptance', () => {
  const harness = (options: {
    historyEnabled?: boolean;
    store?: Partial<SessionStore>;
    chunks?: MessageChunk[];
    pauseAfter?: {chunks: number; until: Promise<void>};
  } = {}) => {
    const sent: OutgoingMessage[] = [];
    const ws = {
      send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
      // In the real app, connectionHandler attaches userId to the ws object.
      userId: 'u1',
      readyState: 1 // OPEN
    } as unknown as WebSocket & {userId: string};

    const chunks = options.chunks || [{type: 'text', text: 'hi'}, {type: 'stop', stopReason: 'end_turn'}];
    const stream = async function* (): AsyncGenerator<MessageChunk> {
      for (const [position, chunk] of chunks.entries()) {
        if (options.pauseAfter && position === options.pauseAfter.chunks) await options.pauseAfter.until;
        yield chunk;
      }
    };

    const orchestrator = {
      processMessageStream: jest.fn(stream)
    } as unknown as ChatOrchestrator;

    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const store = (options.store || {}) as SessionStore;

    // The ticket defines the new signature for createMessageHandler.
    const handle = (createMessageHandler as any)(orchestrator, store, {
      transport: {history: {enabled: options.historyEnabled ?? false}}
    });

    return {
      session,
      sent,
      ws,
      send: (msg: unknown) => handle(ws, session, msg),
    };
  };

  it('delivers the conversation list', async () => {
    const summary: SessionSummary = {
      sessionId: 's2',
      createdAt: new Date('2026-01-15T14:30:00Z'),
      updatedAt: new Date('2026-01-15T14:35:00Z'),
      entryCount: 5
    };
    const listFor = jest.fn<SessionStore['listFor'] & ((...args: any[]) => any)>().mockResolvedValue([summary]);
    const h = harness({historyEnabled: true, store: {listFor}});

    await h.send({type: 'list_conversations', limit: 10});

    expect(h.sent).toContainEqual(expect.objectContaining({
      type: 'conversation_list',
      conversations: [{
        sessionId: 's2',
        createdAt: '2026-01-15T14:30:00Z',
        updatedAt: '2026-01-15T14:35:00Z',
        entryCount: 5
      }]
    }));
    expect(listFor).toHaveBeenCalledWith('u1', expect.objectContaining({limit: 10}));
  });

  it('authorization and regression', async () => {
    const listFor = jest.fn<SessionStore['listFor'] & ((...args: any[]) => any)>().mockResolvedValue([]);
    const h = harness({historyEnabled: true, store: {listFor}});

    // Frame carrying another user's userId should be ignored in favor of ws.userId
    await h.send({type: 'list_conversations', userId: 'another-user'});

    expect(listFor).toHaveBeenCalledWith('u1', expect.anything());
  });

  it('opt-in configuration', async () => {
    const listFor = jest.fn<SessionStore['listFor'] & ((...args: any[]) => any)>().mockResolvedValue([]);
    const h = harness({historyEnabled: false, store: {listFor}});

    await h.send({type: 'list_conversations'});

    expect(h.sent).toContainEqual(expect.objectContaining({
      type: 'error',
      code: 'UNSUPPORTED'
    }));
    expect(listFor).not.toHaveBeenCalled();
  });

  it('unsupported store', async () => {
    // Store with no listFor
    const h = harness({historyEnabled: true, store: {}});

    await h.send({type: 'list_conversations'});

    expect(h.sent).toContainEqual(expect.objectContaining({
      type: 'error',
      code: 'UNSUPPORTED'
    }));
  });

  it('non-blocking handling', async () => {
    const {until, release} = deferred();
    const listFor = jest.fn<SessionStore['listFor'] & ((...args: any[]) => any)>().mockResolvedValue([]);
    const h = harness({
      historyEnabled: true,
      store: {listFor},
      pauseAfter: {chunks: 1, until}
    });

    // Start a streaming user_message
    const userMessagePromise = h.send({type: 'user_message', content: 'hello'});

    // Send list_conversations while streaming
    await h.send({type: 'list_conversations'});

    // Should be answered before the user_message finishes
    expect(h.sent).toContainEqual(expect.objectContaining({type: 'conversation_list'}));
    expect(h.sent.map(f => f.type)).not.toContain('stream_end');

    release();
    await userMessagePromise;
    expect(h.sent.map(f => f.type)).toContain('stream_end');
  });
});

